// Asteroid Escape game – minimal implementation
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  // full‑window canvas
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  // player ship (triangle)
  const player = { x: canvas.width / 2, y: canvas.height * 0.85, size: 20, speed: 4, boost: 2 };
  const keys = { ArrowLeft: false, ArrowRight: false, ArrowUp: false };

  // asteroids
  const asteroids = [];
  let spawnTimer = 0;
  const spawnInterval = 1000; // ms
  let lastTime = 0;
  let score = 0;
  let gameOver = false;

  const onKey = (e, down) => {
    if (e.key in keys) {
      keys[e.key] = down;
      e.preventDefault();
    }
  };
  window.addEventListener('keydown', e => onKey(e, true));
  window.addEventListener('keyup', e => onKey(e, false));

  const spawnAsteroid = () => {
    const radius = Math.random() * 15 + 10;
    const x = Math.random() * (canvas.width - 2 * radius) + radius;
    const speed = Math.random() * 2 + 1;
    asteroids.push({ x, y: -radius, radius, speed });
  };

  const update = (delta) => {
    // player movement
    if (keys.ArrowLeft) player.x -= player.speed;
    if (keys.ArrowRight) player.x += player.speed;
    // keep within bounds
    player.x = Math.max(player.size, Math.min(canvas.width - player.size, player.x));
    if (keys.ArrowUp) player.y -= player.boost;
    // spawn asteroids
    spawnTimer += delta;
    if (spawnTimer > spawnInterval) {
      spawnTimer = 0;
      spawnAsteroid();
    }
    // move asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // remove off‑screen
      if (a.y - a.radius > canvas.height) {
        asteroids.splice(i, 1);
        score++;
      }
    }
    // collision detection (circle vs circle approximation)
    const px = player.x, py = player.y, pr = player.size;
    for (const a of asteroids) {
      const dx = a.x - px;
      const dy = a.y - py;
      const dist = Math.hypot(dx, dy);
      if (dist < pr + a.radius) {
        gameOver = true;
        break;
      }
    }
  };

  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // player triangle
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(player.x, player.y - player.size);
    ctx.lineTo(player.x - player.size, player.y + player.size);
    ctx.lineTo(player.x + player.size, player.y + player.size);
    ctx.closePath();
    ctx.fill();
    // asteroids
    ctx.fillStyle = '#a52a2a';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText('Score: ' + score, 10, 30);
    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 20);
      ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2 + 20);
    }
  };

  const loop = (timestamp) => {
    if (!lastTime) lastTime = timestamp;
    const delta = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(delta);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
})();
